<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';Auth::requirePermission('settings','view');$pageTitle='تنظیمات سایت';
$keys=['company_name'=>'نام شرکت','site_title'=>'عنوان سایت','hero_subtitle'=>'زیرعنوان هیرو','meta_description'=>'توضیحات متا','footer_text'=>'متن فوتر','primary_color'=>'رنگ اصلی','logo_path'=>'مسیر لوگو'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::can('settings','edit')){flash('برای ویرایش تنظیمات دسترسی ندارید.','danger');redirect('/admin/settings.php');}if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/settings.php');}foreach($keys as $key=>$label){$type=in_array($key,['hero_subtitle','meta_description'],true)?'textarea':($key==='primary_color'?'color':($key==='logo_path'?'image':'text'));Database::execute('INSERT INTO site_settings (setting_key,setting_value,setting_type,updated_at) VALUES (?,?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value), setting_type=VALUES(setting_type), updated_at=NOW()',[$key,$_POST[$key]??'',$type]);}if(!empty($_FILES['logo']['name'])){$up=Upload::save($_FILES['logo'],'uploads/logo',Upload::IMAGE_EXTENSIONS);if($up['ok'])Database::execute('INSERT INTO site_settings (setting_key,setting_value,setting_type,updated_at) VALUES ("logo_path",?,"image",NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value), updated_at=NOW()',[$up['file_path']]);else{flash($up['error'],'danger');redirect('/admin/settings.php');}}flash('تنظیمات ذخیره شد.');redirect('/admin/settings.php');}
require __DIR__.'/../views/partials/admin-header.php';?>
<form class="card admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><div class="grid grid-2"><?php foreach($keys as $key=>$label):?><label class="form-field"><span><?=e($label)?></span><?php if(in_array($key,['hero_subtitle','meta_description'],true)):?><textarea name="<?=e($key)?>"><?=e(setting($key,$key==='hero_subtitle'?'سامانه هلدینگ سبحان و بخش های وابسته.':''))?></textarea><?php else:?><input <?= $key==='primary_color'?'type="color"':'' ?> name="<?=e($key)?>" value="<?=e(setting($key,$key==='primary_color'?'#2563eb':''))?>"><?php endif;?></label><?php endforeach;?><label class="form-field"><span>آپلود لوگو</span><input type="file" name="logo" accept="image/png,image/jpeg"><small><?=e(setting('logo_path'))?></small></label></div><button class="btn btn-primary">ذخیره تنظیمات</button></form></section></main></div><script src="/assets/js/app.js"></script></body></html>
